import React, { useState } from "react";

export default function AdminDashboard({ reports, ngoList, token, setMsg }) {
  const [approveMsg, setApproveMsg] = useState("");

  function approveNGO(id) {
    // Approve NGO is not implemented in demo backend.
    setApproveMsg('Approve action is not available in demo.');
  }

  return (
    <div className="panel">
      <h3>Admin Reports</h3>

      {reports ? (
        <>
          <p><strong>Total Donations:</strong> {reports.donations ? reports.donations.length : 0}</p>
          <p><strong>Total Volunteers:</strong> {reports.volunteers ? reports.volunteers.length : 0}</p>
          <p><strong>Total Feedbacks:</strong> {reports.feedbacks ? reports.feedbacks.length : 0}</p>
        </>
      ) : (
        <p>Loading reports...</p>
      )}

      <h4>Approve NGOs</h4>
      <ul>
        {ngoList && ngoList.length ? (
          ngoList.map(n => (
            <li key={n.id}>
              {n.name} — {n.status}
              {n.status === "Pending" && (
                <button onClick={() => approveNGO(n.id)} style={{ marginLeft: "10px" }}>
                  Approve
                </button>
              )}
            </li>
          ))
        ) : (
          <p>No NGOs found.</p>
        )}
      </ul>

      {approveMsg && <p className="msg">{approveMsg}</p>}
    </div>
  );
}
